jQuery(document).ready(function() {
    updateSlider()
    jQuery(window).resize(updateSlider)
});

jQuery('.modal__close-btn-inner').on('click', function(e) {
    jQuery('#modal').css({'display': 'none'});
    jQuery('body').removeClass('lock');
    jQuery('#modal__content').removeClass('modal__content-video').removeClass('modal__content-contact').removeClass('modal__content-video-vertical').html('')
})

jQuery('.gallery-item__link').on('click', function(e) {
    e.preventDefault()
    let isVertical = false;
    if(e.currentTarget.dataset.vertical != undefined) isVertical = true;

    jQuery('body').addClass('lock');
    loadVideo(e.currentTarget.dataset.url, isVertical)
})

jQuery('#modal-contact-btn').on('click', function(e) {
    e.preventDefault()
    jQuery('body').addClass('lock');
    loadContacts()
})


function loadVideo(id, isVertical = false) {
    let uid = id.split('-')[1].split('_')[0];
    let vid = id.split('-')[1].split('_')[1];

    if(isVertical) {
        jQuery('#modal__content').addClass('modal__content-video-vertical').html(`<div class="modal__video_vertical"><div class="modal__video-loader-outline"><div class="modal__video-loader-wrap"><span class="loader"></span><span class="h400 modal__video-loader-text">Загрузка видео<span></div></div><iframe src="https://vk.com/video_ext.php?oid=-${uid}}&id=${vid}&hd=2&autoplay=1" allow="autoplay; encrypted-media; fullscreen; picture-in-picture; screen-wake-lock;" frameborder="0" allowfullscreen></iframe></div>`)    
    } else {
        jQuery('#modal__content').addClass('modal__content-video').html(`<div class="modal__video"><div class="modal__video-loader-outline"><div class="modal__video-loader-wrap"><span class="loader"></span><span class="h400 modal__video-loader-text">Загрузка видео<span></div></div><iframe src="https://vk.com/video_ext.php?oid=-${uid}&id=${vid}&hd=2&autoplay=1" allow="autoplay; encrypted-media; fullscreen; picture-in-picture; screen-wake-lock;" frameborder="0" allowfullscreen></iframe></div>`)    
    }
    jQuery('#modal').css({"display": "flex"});
}

function loadContacts() {
    jQuery('#modal__content').addClass('modal__content-contact').html(`<div class="modal__contact-form"><div class="modal__form-wrapper"><div class="modal__form-content"><div class="modal__form-text"><h3 class="modal__text-title h750">Если у вас остались вопросы, свяжитесь с нами.</h3><div class="modal__text-description p300">Введите имя и номер телефона, чтобы мы могли связаться и обсудить ваш проект.</div></div><div class="modal__form-wrap"><form class="modal__form"><input class="contact__input" type="text" placeholder="Ваше имя"><input class="contact__input" type="phone" placeholder="Ваш номер телефона"><input class="button" type="submit" value="Отправить"></form><p class="modal__form-privacy-policy c200">Нажимая на кнопку «Отправить», вы подтверждаете свое согласие на обработку персональных данных и соглашаетесь с <a href="#">политикой конфиденциальности</a></p></div></div></div></div>`)
    jQuery('#modal').css({"display": "flex"});
}

function updateSlider() {
    let slides = 4;
    if(window.screen.width <= 1279) slides = 3;
    if(window.screen.width <= 767) slides = 1;

    jQuery('.owl-carousel').owlCarousel({
        margin: 16,
        items: slides,
        nav: true,
        autoWidth: true,
    });
}
